<?php
require __DIR__ . '/backend/common.php';
$paper_count = (int) ($conn->query("SELECT COUNT(*) AS total FROM papers WHERE status = 'approved'")->fetch_assoc()['total'] ?? 0);
$member_count = (int) ($conn->query("SELECT COUNT(*) AS total FROM users WHERE is_active = 1")->fetch_assoc()['total'] ?? 0);
$project_count = (int) ($conn->query("SELECT COUNT(*) AS total FROM projects WHERE approval = 'approved' AND status <> 'Completed'")->fetch_assoc()['total'] ?? 0);
$papers = $conn->query("SELECT id, title, authors, abstract, category FROM papers WHERE status = 'approved' ORDER BY id DESC LIMIT 3")->fetch_all(MYSQLI_ASSOC);
$projects = $conn->query("SELECT p.id, p.title, p.description, p.department, p.status, u.full_name FROM projects p JOIN users u ON u.id = p.user_id WHERE p.approval = 'approved' AND p.status <> 'Completed' ORDER BY p.id DESC LIMIT 3")->fetch_all(MYSQLI_ASSOC);
$featured_papers = [
    ['title' => 'Research that improves everyday systems', 'abstract' => 'Search peer-reviewed work, discover methods, and build on ideas across disciplines.', 'category' => 'Research discovery'],
    ['title' => 'A practical home for collaboration', 'abstract' => 'Find a project, ask a precise question, or publish the next iteration of your work.', 'category' => 'Collaboration'],
];
$featured_projects = [
    ['title' => 'Open research opportunities', 'description' => 'Browse live projects and meet researchers who are looking for focused collaborators.', 'department' => 'Across UIU', 'status' => 'Open'],
    ['title' => 'Your next research question', 'description' => 'Start a project workspace with a clear problem statement, outcomes, and collaborators.', 'department' => 'Across UIU', 'status' => 'Open'],
];
?>
